#include <stdint.h>
#include <stddef.h>

int spi_transfer_bits(const uint8_t *tx_data, uint8_t *rx_data,
                      int chunk_count, int bit_mode, int *total_bits)
{
    if (total_bits != NULL) {
        *total_bits = 0;
    }

    if (bit_mode != 1 && bit_mode != 2 && bit_mode != 4 && bit_mode != 8) {
        return -1;
    }
    if (tx_data == NULL || rx_data == NULL || chunk_count <= 0) {
        return -2;
    }

    int bits = chunk_count * bit_mode;
    if (total_bits != NULL) {
        *total_bits = bits;
    }
    return bits;
}
